import Combine

class Settings: ObservableObject {
    @Published var title = "Original"
}

let s = Settings()
var captured = ""
let sub = s.objectWillChange.sink {
    captured = s.title
}

s.title = "Updated"
print("Captured: \(captured)")

import Combine

