import Combine

class Wallet: ObservableObject {
    var coins: Int = 50 {
        willSet {
            objectWillChange.send()
        }
    }
}

let w = Wallet()
var notified = false
let sub = w.objectWillChange.sink {
    notified = true
}

w.coins = 75
print("Notified: \(notified), Coins: \(w.coins)")

import Combine

class Temperature: ObservableObject {
    @Published var celsius: Double = 0.0
    var fahrenheit: Double {
        return (celsius * 9.0 / 5.0) + 32.0
    }
}

let t = Temperature()
t.celsius = 25.0
print("Fahrenheit: \(Int(t.fahrenheit))")

