import Combine

class TaskTracker: ObservableObject {
    @Published var completedCount: Int = 0

    func completeTask() {
        completedCount += 1
    }
}

let tracker = TaskTracker()
tracker.completeTask()
tracker.completeTask()
print("Completed tasks: \(tracker.completedCount)")

import Combine

class MessageFeed: ObservableObject {
    @Published var messages: [String] = []

    func postMessage(_ text: String) {
        messages.append(text)
    }
}

let feed = MessageFeed()
feed.postMessage("Welcome")
feed.postMessage("SwiftUI")
print("Feed count: \(feed.messages.count)")

import Combine

class CustomCounter: ObservableObject {
    var value: Int = 0 {
        willSet {
            objectWillChange.send()
        }
    }
}

let counter = CustomCounter()
var changeDetected = false
let sub = counter.objectWillChange.sink {
    changeDetected = true
}

counter.value = 10
print("Value: \(counter.value), Change detected: \(changeDetected)")
